use std::fmt::Write as _;
use std::io::Write as _;
use std::process::ExitCode;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }
    let w = dims.width;
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= dims.height);
    let c = src[y * w + x];
    let sum = 4u * c + src[y * w + xl] + src[y * w + xr] + src[yu * w + x] + src[yd * w + x];
    dst[y * w + x] = sum / 8u;
}
"#;

const WORKGROUP: u32 = 8;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("unexpected end of input reading {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid number {tok:?} for {what}"))
    };
    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("grid size {width}x{height} out of range 1..=512"));
    }
    if steps > 1000 {
        return Err(format!("steps {steps} out of range 0..=1000"));
    }
    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for i in 0..count {
        let v = next(&format!("cell {i}"))?;
        if v > 1_000_000 {
            return Err(format!("cell value {v} out of range 0..=1000000"));
        }
        cells.push(v as u32);
    }
    if tokens.next().is_some() {
        return Err("trailing data after grid".to_string());
    }
    Ok(Grid {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

fn u32s_to_bytes(values: &[u32]) -> Vec<u8> {
    values.iter().flat_map(|v| v.to_le_bytes()).collect()
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .ok_or("no GPU adapter available")?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default(), None)
        .await
        .map_err(|e| format!("failed to open GPU device: {e}"))?;

    let byte_len = (grid.cells.len() * std::mem::size_of::<u32>()) as u64;
    let storage_usage =
        wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::COPY_SRC;
    let make_storage = |label| {
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some(label),
            size: byte_len,
            usage: storage_usage,
            mapped_at_creation: false,
        })
    };
    let buffers = [make_storage("grid a"), make_storage("grid b")];
    queue.write_buffer(&buffers[0], 0, &u32s_to_bytes(&grid.cells));

    let dims = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("dims"),
        size: 8,
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    queue.write_buffer(&dims, 0, &u32s_to_bytes(&[grid.width, grid.height]));

    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: byte_len,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat step"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: dims.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: buffers[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: buffers[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&Default::default());
    for step in 0..grid.steps {
        // Separate passes so each step sees the previous step's complete output.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[(step % 2) as usize], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = &buffers[(grid.steps % 2) as usize];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, byte_len);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::Maintain::Wait);
    rx.recv()
        .map_err(|_| "GPU readback was dropped".to_string())?
        .map_err(|e| format!("GPU readback failed: {e}"))?;
    let out = {
        let data = slice.get_mapped_range();
        data.chunks_exact(4)
            .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            .collect()
    };
    readback.unmap();
    Ok(out)
}

fn run() -> Result<String, String> {
    let path = std::env::args_os()
        .nth(1)
        .ok_or("usage: heat <input-file>")?;
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {}: {e}", path.to_string_lossy()))?;
    let grid = parse(&text)?;
    let cells = if grid.steps == 0 {
        grid.cells.clone()
    } else {
        pollster::block_on(run_gpu(&grid))?
    };

    let mut out = String::with_capacity(cells.len() * 8 + 32);
    for row in cells.chunks(grid.width as usize) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v}");
        }
        out.push('\n');
    }
    let total: u64 = cells.iter().map(|&v| u64::from(v)).sum();
    let _ = writeln!(out, "SUM {total}");
    Ok(out)
}

fn main() -> ExitCode {
    match run() {
        Ok(out) => {
            let mut stdout = std::io::stdout().lock();
            if stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()).is_err() {
                return ExitCode::FAILURE;
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

