        .map_err(|e| format!("GPU readback failed: {e}"))?;
    let out = {
        let data = slice.get_mapped_range();
        data.chunks_exact(4)
            .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            .collect()
    };
    readback.unmap();
    Ok(out)
}

fn run() -> Result<String, String> {
    let path = std::env::args_os()
        .nth(1)
        .ok_or("usage: heat <input-file>")?;
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {}: {e}", path.to_string_lossy()))?;
    let grid = parse(&text)?;
    let cells = if grid.steps == 0 {
        grid.cells.clone()
    } else {
        pollster::block_on(run_gpu(&grid))?
    };

    let mut out = String::with_capacity(cells.len() * 8 + 32);
    for row in cells.chunks(grid.width as usize) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v}");
        }
        out.push('\n');
    }
    let total: u64 = cells.iter().map(|&v| u64::from(v)).sum();
    let _ = writeln!(out, "SUM {total}");
    Ok(out)
}

fn main() -> ExitCode {
    match run() {
        Ok(out) => {
            let mut stdout = std::io::stdout().lock();
            if stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()).is_err() {
                return ExitCode::FAILURE;
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

